/** @brief GNSS handler using UBX protocol library 
 * 
 * When activated, set auto receive for the UBX protocol commands used:
 * UBX-NAV-PVT: position, velocity and time
 * ***REMOVED*** UBX-NAV-DOP: dilution of precision, for horizontal DOP
 * ***REMOVED*** UBX-NAV-SAT: enumeration of satellites in view, for number of sats.
 * Based on examples by Paul Clark, SparkFun Electronics
 * https://github.com/sparkfun/SparkFun_u-blox_GNSS_Arduino_Library
 * 
 * ***REMOVED*** The two removed packets were not providing any additional
 * useful information. HDOP was always zero. NSATS was the total number of
 * satellites, regardless of their status in computing a fix.
*/

#include "utils/functions.h"
#include "gps_connector.h"
#include "utils/api_data_cache.h"
#include <SD.h>

#define GPS_INVALID_YEAR 2000
#define GPS_INVALID_MONTH 1
#define GPS_INVALID_DAY 1
#define GPS_INVALID_HOUR 0
#define GPS_INVALID_MINUTE 0
#define GPS_INVALID_SECOND 0

#define NNE 22.5
#define ENE (NNE + 45)
#define ESE (ENE + 45)
#define SSE (ESE + 45)
#define SSW (SSE + 45)
#define WSW (SSW + 45)
#define WNW (WSW + 45)
#define NNW (WNW + 45)

GpsConnector::GpsConnector(TeenyUbloxConnect& gnss, HardwareSerial& serial) : Worker<GnssData>({
                                                       .location_valid=false,
                                                       .date_valid=false,
                                                       .time_valid=false,
                                                       .latitude=0,
                                                       .longitude=0,
                                                       .altitudeMSL=0,
                                                       .heading_degree=0,
                                                       .heading=GnssData::UNKNOWN,
                                                       .satsInView=0,
                                                       .pdop=0,
                                                       .year=0,
                                                       .month=0,
                                                       .day=0,
                                                       .hour=0,
                                                       .minute=0,
                                                       .second=0,
                                                       .protocolVersionHigh=0,
                                                       .protocolVersionLow=0
                                                   }), _gnss(gnss), _serial_conn(serial), _tried_115200_at(0), _tried_38400_at(0), _tried_9600_at(0), _init_at(0), _last_latitude(0), _last_longitude(0) {
}
/**
 * @return true if initialized GNSS library, false if no connection with module.
*/
bool GpsConnector::activate(bool retry) {
  // From Sparkfun examples/Example12_UseUart
  // Assume that the U-Blox GNSS is running at 9600 baud (the default) or at 38400 baud.
  if (!retry) {
#ifdef CONFIG_IDF_TARGET_ESP32S3 // Core S3SE fix using the correct serial pins
    _serial_conn.begin(38400, SERIAL_8N1, RXD2, TXD2);
#else
    _serial_conn.begin(38400);
#endif

    _init_at = millis();
  }
  if (_tried_115200_at == 0 && (millis() - _init_at > 1000)) { // Wait for device to completely startup
    _tried_115200_at = millis();
    _serial_conn.updateBaudRate(115200);
    M5_LOGD("GNSS: Try at 115200 baud");
    if (_gnss.begin(_serial_conn, 500)) {
      M5_LOGD("GNSS: connected at 115200 baud"); // no need to set module to 38.4
    }
    else {
      return false;
    }
  }
  else if (_tried_38400_at == 0 && _tried_115200_at > 0 && (millis() - _tried_115200_at > 1200)) { // Wait for device to completely startup
    _tried_38400_at = millis();
    _serial_conn.updateBaudRate(38400);
    M5_LOGD("GNSS: Try at 38400 baud");
    if (_gnss.begin(_serial_conn, 500)) {
      M5_LOGD("GNSS: connected at 38400 baud"); // no need to set module to 38.4
    }
    else {
      return false;
    }
  }
  else if (_tried_9600_at == 0 && _tried_38400_at > 0 && (millis() - _tried_38400_at > 1200)) {
    _tried_9600_at = millis();
    _serial_conn.updateBaudRate(9600);
    M5_LOGD("GNSS: Try at 9600 baud");
    if (_gnss.begin(_serial_conn, 1000)) {
      M5_LOGD("GNSS: connected at 9600 baud, switching to 38400");
      _gnss.setSerialRate(38400);
      delay(100); // recovery time for gnss module baud rate change
      _serial_conn.updateBaudRate(38400);
    }
    else {
      return false;
    }
  }
  else {
    return false;
  }

  // Confirm that we actually have a connection
  data.protocolVersionHigh = _gnss.getProtocolVersionHigh();
  data.protocolVersionLow = _gnss.getProtocolVersionLow();
  M5_LOGD("GNSS: u-blox protocol version %02d.%02d",
              data.protocolVersionHigh, data.protocolVersionLow);

  // Check the current dynamic model on startup
  // This will help us verify if the setting persisted after power cycling
  M5_LOGD("GNSS: Reading current dynamic model...");
  readDynamicModelFromGPS();

  // Send UBX, disable NMEA-0183 messages that we are ignoring anyway.
  _gnss.setPortOutput(COM_PORT_UART1, COM_TYPE_UBX);

  // Set Auto on NAV-PVT for non-blocking access
  // getPVT() will return true if a new navigation solution is available
  _gnss.setAutoNAVPVT(true); // Tell the GNSS to send the solution as it is computed (1 second)
  _gnss.setAutoNAVSAT(false); // Disable navsat by default (navsat worker handles this)

  // Announce/perform restore path on boot (relies on internal backup domain)
  restoreGpsMemoryFromNVS();

  // Try to restore full database from SD if available
  restoreDatabaseFromSD();

  // Try to inject warm-start seed from SD if present
  injectWarmStartSeedFromSD();

  return true;
}

// Simple warm seed format
// magic 0x47574D53 ('GWMS'), version 1, lat/lon in 1e-7 deg, alt mm, date/time
struct WarmSeedBinV1 {
  uint32_t magic;     // 'GWMS'
  uint16_t version;   // 1
  int32_t lat_e7;
  int32_t lon_e7;
  int32_t alt_mm;     // altitude MSL in mm
  uint16_t year;
  uint8_t month, day, hour, minute, second;
};

// Age limits in seconds
static constexpr uint32_t kSeedMaxAge = 7 * 24 * 3600; // 7 days
static constexpr uint32_t kDbdMaxAge = 12 * 3600; // 12 hours

static constexpr uint32_t kSeedMagic = 0x47574D53; // GWMS
static constexpr uint16_t kSeedVer = 1;
static constexpr const char* kSeedDir = "/gnss";
static constexpr const char* kSeedPath = "/gnss/warm_seed.bin";
static constexpr const char* kDbdPath = "/gnss/dbd_latest.bin";

// Forward declarations
class GpsConnector;
static bool sendMgaIniTimeUtc(GpsConnector* gps, uint16_t year, uint8_t month, uint8_t day, 
                              uint8_t hour, uint8_t minute, uint8_t second);
static bool sendMgaIniPosLlh(GpsConnector* gps, int32_t lat_1e7, int32_t lon_1e7, int32_t alt_mm);

bool GpsConnector::saveWarmStartSeedToSD() {
  // Ensure we have valid data
  if (!(data.location_valid && data.date_valid && data.time_valid)) {
    M5_LOGW("GPS: Cannot save warm seed — invalid or incomplete GNSS data");
    return false;
  }

  // Ensure directory exists
  if (!SD.exists(kSeedDir)) {
    if (!SD.mkdir(kSeedDir)) {
      M5_LOGE("GPS: Failed to create %s directory on SD", kSeedDir);
      return false;
    }
  }

  WarmSeedBinV1 seed{};
  seed.magic = kSeedMagic;
  seed.version = kSeedVer;
  seed.lat_e7 = static_cast<int32_t>(data.latitude * 1e7);
  seed.lon_e7 = static_cast<int32_t>(data.longitude * 1e7);
  seed.alt_mm = static_cast<int32_t>(data.altitudeMSL * 1000.0);
  seed.year = data.year;
  seed.month = data.month;
  seed.day = data.day;
  seed.hour = data.hour;
  seed.minute = data.minute;
  seed.second = data.second;

  File f = SD.open(kSeedPath, FILE_WRITE);
  if (!f) {

/** @brief Manage position fix and date-time from GNSS receiver. 
 * 
 * Based on u-blox 8 receiver integrated Beitian BN-880 module, using the UBX communications
 * protocol instead of the usual NMEA-183. The problem with NMEA is that it was really 
 * designed for boats, where close enough to see with binoculars was good enough (well, not
 * really but it makes for a good story). The real issue is that it's hard to get consistent
 * fix and time data by parsing NMEA sentences.
 * 
*/

#ifndef BGEIGIEZEN_GPS_SENSOR_H_
#define BGEIGIEZEN_GPS_SENSOR_H_

#include <Arduino.h>
#include <RBD_Timer.h>
#include <Worker.hpp>
#include <user_config.h>

#include <TeenyUbloxConnect.h>
#include "gps_platform_model.h"

struct GnssData {
  // When true, the item related to each Boolean is valid and updated in the
  // most recent poll of the gps_connector worker by the controller. If the 
  // gps_connector doesn't have a new fix because it only becomes available
  // every 1 second, then the corresponding Boolean becomes false.
  // If stale, render in gray/white text. 
  bool location_valid;
  bool date_valid;
  bool time_valid;

  bool valid() const {
    return location_valid && date_valid && time_valid;
  }

  enum Heading {
    UNKNOWN,
    NORTH,
    NORTHEAST,
    EAST,
    SOUTHEAST,
    SOUTH,
    SOUTHWEST,
    WEST,
    NORTHWEST,
  };

  // Position
  double latitude;  // Longitude: deg
  double longitude; // Longitude: deg
  double altitudeMSL;  // above mean sea level in meters
  double heading_degree; // in degrees
  Heading heading;

  // Confidence
  uint8_t satsInView;  // (NavSat) satellites used to calculate fix
  uint8_t  numSV;  // (NavPvt) Number of satellites used in Nav Solution
  double pdop;  // position dilution of precision (not horizontal)
  uint32_t hAcc;  // mm Horizontal accuracy estimate for Long/Lat
  uint32_t vAcc;  // mm Vertical accuracy estimate for Long/Lat
  int32_t  velN;  // mm/s NED north velocity
  int32_t  velE;  // mm/s NED east velocity
  int32_t  velD;  // mm/s NED down velocity
  int32_t  gSpeed;  // Ground Speed (2-D)
  int32_t  headMot;  // Heading of motion (2-D)
  uint32_t sAcc;
  uint32_t headAcc;
  bool invalidLlh;  // NAVPVT[78] flags3 bit 0


  // Date & Time
  uint16_t year;
  uint8_t month;
  uint8_t day;
  uint8_t hour;
  uint8_t minute;
  uint8_t second;

  // Debug info
  uint8_t protocolVersionHigh;
  uint8_t protocolVersionLow;

};

/**
 * GPS device worker, produces the current GPS location.
 */
class GpsConnector : public Worker<GnssData> {
 public:

  explicit GpsConnector(TeenyUbloxConnect& _gnss, HardwareSerial& serial);

  virtual ~GpsConnector() = default;


  /**
   * Backup U-blox GPS memory (almanac, ephemeris, satellite data) to M5Stack NVS
   * @return true if backup was successful
   */
  bool backupGpsMemoryToNVS();

  /**
   * Restore U-blox GPS memory from M5Stack NVS for faster startup
   * @return true if restore was successful
   */
  bool restoreGpsMemoryFromNVS();

  /**
   * Save a warm-start seed (time/position) to SD card for faster startup without VBAT.
   * File path: /gnss/warm_seed.bin
   * @return true if file written
   */
  bool saveWarmStartSeedToSD();

  /**
   * Load warm-start seed from SD card and prepare for injection.
   * Current implementation validates and logs the seed.
   * @return true if seed loaded
   */
  bool injectWarmStartSeedFromSD();

  /**
   * Dump the GNSS database (UBX-MGA-DBD) to SD card.
   * File path: /gnss/dbd_latest.bin (raw UBX frames)
   */
  bool dumpDatabaseToSD();

  /**
   * Restore the GNSS database from SD card by replaying stored UBX frames.
   * File path: /gnss/dbd_latest.bin
   */
  bool restoreDatabaseFromSD();

  bool activate(bool retry) override;

  int8_t produce_data() override;

  /**
   * Set the GPS dynamic platform model
   * @param model The dynamic model to set (e.g., DYNMODEL_PORT, DYNMODEL_AIR4)
   * @param saveToFlash If true, saves the setting to flash memory so it persists after power cycles
   * @return true if successful, false otherwise
   */
  bool setDynamicModel(UbxDynamicModel model, bool saveToFlash);

  /**
   * Set the GPS dynamic platform model (RAM only version)
   * @param model The dynamic model to set (e.g., DYNMODEL_PORT, DYNMODEL_AIR4)
   * @return true if successful, false otherwise
   */
  bool setDynamicModel(UbxDynamicModel model);

  /**
   * Get the current GPS dynamic platform model
   * @return The current dynamic model
   */
  UbxDynamicModel getDynamicModel();

  /**
   * Read the current dynamic model directly from the GPS module
   * @return true if successful, false otherwise
   */
  bool readDynamicModelFromGPS();

  /**
   * Send a raw UBX message to the GPS module
   * @param msgClass UBX message class
   * @param msgID UBX message ID
   * @param payload Payload data
   * @param payloadSize Size of the payload
   * @return true if successful, false otherwise
   */
  bool sendUBXMessage(uint8_t msgClass, uint8_t msgID, const uint8_t* payload, size_t payloadSize);
  /**
   * Request the GNSS module to enter Backup mode and save its state.
   * Uses UBX-RXM-PMREQ with flags = 0x00000001.
   * Should be called just before power is removed.
   * @return true if the UBX frame was sent.
   */
  bool requestBackup();

  /**
   * Calculate UBX message checksum
   * @param data Data to calculate checksum for
   * @param len Length of data
   * @param cka Pointer to store CK_A
   * @param ckb Pointer to store CK_B
   */
  void calculateChecksum(const uint8_t* data, size_t len, uint8_t* cka, uint8_t* ckb);

 protected:
  void deactivate() override;

 private:
  /* u-blox UBX protocol query PVT gets position, velocity & time in one call.
   * The call returns false if no new fix has been received. In other words,
   * each call only succeeds once until the next fix update.
   * Use pdop and satsInView to determine acceptability.
  */
  TeenyUbloxConnect& _gnss;
  HardwareSerial& _serial_conn;
  uint32_t _tried_115200_at;
  uint32_t _tried_38400_at;
  uint32_t _tried_9600_at;
  uint32_t _init_at;

  double _last_latitude;
  double _last_longitude;

  // Current GPS dynamic model
  UbxDynamicModel _current_model = DYNMODEL_PORT;

  // Age each item. If the corresponding timer times out, it's stale.
  RBD::Timer location_timer{GPS_FIX_AGE_LIMIT};
  RBD::Timer date_timer{GPS_FIX_AGE_LIMIT};
  RBD::Timer time_timer{GPS_FIX_AGE_LIMIT};
  RBD::Timer time_getpvt{GPS_FIX_AGE_LIMIT};  // if no response from getPVT()
};

#endif //BGEIGIEZEN_GPS_SENSOR_H_

