    } else if((protocolVersionHigh == 34) && (protocolVersionLow == 10)) {
      ubloxModuleType = UBLOX_M10_MODULE;
      return true;
    } else if(protocolVersionHigh < 18) {
      // u-blox 7 and earlier (e.g. UBX-G7020-KT, protocol 14.x/15.x)
      // use the same CFG-PRT/NAV-PVT command set as M8
      ubloxModuleType = UBLOX_M8_MODULE;
      return true;
    }
  }
}
return false;

