  for(uint8_t i = 0; i < 4; i++) commandPacket.payload[kvIndex + i] = gnssKey >> (8 * i);
  commandPacket.payload[kvIndex + 4] = enable;
  kvIndex += 5;
  gnssKey = UBLOX_CFG_SIGNAL_GAL_ENA;
