  for(uint8_t i = 0; i < 4; i++) commandPacket.payload[56 + i] = REDACTED >> (8 * i);
  commandPacket.validPacket = true;
  if(sendCommandPacket(true, true, maxWait_) &&
     (responsePacket.payloadLength == 74)) {
    uint32_t gnssKey;
    bool gnssEnable;
    uint8_t cfgBlkNum = 0;
    uint8_t cfgSigNum = 0;
