 */
bool GpsConnector::sendUBXMessage(uint8_t msgClass, uint8_t msgID, const uint8_t* payload, size_t payloadSize) {
  // UBX message structure:
  // Sync Char 1: 0xB5
  // Sync Char 2: 0x62
  // Class: 1 byte
  // ID: 1 byte

